{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2125-02-23 15:14:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. You're here today for your scheduled peritoneal dialysis catheter placement, correct?"
    },
    {
      "turn_number": 2,
      "time": "2125-02-23 15:15:00",
      "speaker": "Patient",
      "text": "Yes, that's right. I had to stop warfarin before this, didn't I?"
    },
    {
      "turn_number": 3,
      "time": "2125-02-23 15:16:00",
      "speaker": "Doctor",
      "text": "Yes, we held your warfarin to reduce bleeding risk during surgery. We’ll restart it soon, but at a lower dose."
    },
    {
      "turn_number": 4,
      "time": "2125-02-23 15:17:00",
      "speaker": "Patient",
      "text": "Okay, good. I was worried about my blood clots."
    },
    {
      "turn_number": 5,
      "time": "2125-02-23 15:18:00",
      "speaker": "Doctor",
      "text": "We understand. You’re on clopidogrel and aspirin too, which we’re continuing. Your surgery is set for tomorrow morning."
    },
    {
      "turn_number": 6,
      "time": "2125-02-23 15:19:00",
      "speaker": "Patient",
      "text": "Tomorrow? What about the scar tissue from my past surgeries?"
    },
    {
      "turn_number": 7,
      "time": "2125-02-23 15:20:00",
      "speaker": "Doctor",
      "text": "Good question. We expect some peritoneal adhesions, so the surgeon will perform lysis—freeing up the scar tissue—before placing the catheter."
    },
    {
      "turn_number": 8,
      "time": "2125-02-23 15:21:00",
      "speaker": "Patient",
      "text": "That sounds painful."
    },
    {
      "turn_number": 9,
      "time": "2125-02-23 15:22:00",
      "speaker": "Doctor",
      "text": "We’ll manage your pain carefully. You’ll get IV pain meds at first, then switch to oral ones like oxycodone as you recover."
    },
    {
      "turn_number": 10,
      "time": "2125-02-23 15:23:00",
      "speaker": "Patient",
      "text": "Okay, that helps. My heart has been acting up lately too."
    },
    {
      "turn_number": 11,
      "time": "2125-02-23 15:24:00",
      "speaker": "Doctor",
      "text": "I see you have a history of atrial fibrillation and diastolic heart failure. We’re monitoring your blood pressure and heart rate closely."
    },
    {
      "turn_number": 12,
      "time": "2125-02-23 15:25:00",
      "speaker": "Patient",
      "text": "I’ve been dizzy during dialysis before."
    },
    {
      "turn_number": 13,
      "time": "2125-02-23 15:26:00",
      "speaker": "Doctor",
      "text": "Yes, you were on midodrine 2.5 mg twice daily for that. We’re increasing it to 5 mg twice daily now to help maintain your blood pressure."
    },
    {
      "turn_number": 14,
      "time": "2125-02-23 15:27:00",
      "speaker": "Patient",
      "text": "Oh, so it’s being increased?"
    },
    {
      "turn_number": 15,
      "time": "2125-02-23 15:28:00",
      "speaker": "Doctor",
      "text": "Yes, to support you during fluid shifts after surgery. We want to avoid low blood pressure when you start peritoneal dialysis."
    },
    {
      "turn_number": 16,
      "time": "2125-02-23 15:29:00",
      "speaker": "Patient",
      "text": "Makes sense. And my kidney numbers—are they okay?"
    },
    {
      "turn_number": 17,
      "time": "2125-02-23 15:30:00",
      "speaker": "Doctor",
      "text": "Your creatinine is 2.4, which is expected since you’re on dialysis. We’re watching your electrolytes too—potassium and sodium are normal."
    },
    {
      "turn_number": 18,
      "time": "2125-02-23 15:31:00",
      "speaker": "Patient",
      "text": "And my anemia? I remember getting blood transfusions last time."
    },
    {
      "turn_number": 19,
      "time": "2125-02-23 15:32:00",
      "speaker": "Doctor",
      "text": "Your hemoglobin is 11.5, which is stable. We don’t need a transfusion this time. You’re on folic acid and B12, which helps."
    },
    {
      "turn_number": 20,
      "time": "2125-02-23 15:33:00",
      "speaker": "Patient",
      "text": "Good. I don’t miss those transfusions."
    },
    {
      "turn_number": 21,
      "time": "2125-02-23 15:34:00",
      "speaker": "Doctor",
      "text": "We’ll keep an eye on it. For now, rest up. We’ll see you in the morning before surgery."
    },
    {
      "turn_number": 22,
      "time": "2125-02-24 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Ready for your procedure today?"
    },
    {
      "turn_number": 23,
      "time": "2125-02-24 08:01:00",
      "speaker": "Patient",
      "text": "As ready as I’ll ever be. Nervous about the anesthesia."
    },
    {
      "turn_number": 24,
      "time": "2125-02-24 08:02:00",
      "speaker": "Doctor",
      "text": "You’ll be under general anesthesia, but the team is experienced. Given your sleep-disordered breathing, they’ll monitor you closely after."
    },
    {
      "turn_number": 25,
      "time": "2125-02-24 08:03:00",
      "speaker": "Patient",
      "text": "I can’t use CPAP, so I hope I don’t need a breathing tube again."
    },
    {
      "turn_number": 26,
      "time": "2125-02-24 08:04:00",
      "speaker": "Doctor",
      "text": "We’ll avoid intubation if possible. You’re on 2L oxygen at night—we’ll resume that as needed post-op."
    },
    {
      "turn_number": 27,
      "time": "2125-02-24 13:30:00",
      "speaker": "Doctor",
      "text": "Hi, you’re back from surgery. You did great. The surgeon placed the PD catheter successfully and lysed the adhesions."
    },
    {
      "turn_number": 28,
      "time": "2125-02-24 13:31:00",
      "speaker": "Patient",
      "text": "Oh, thank goodness. Does it hurt?"
    },
    {
      "turn_number": 29,
      "time": "2125-02-24 13:32:00",
      "speaker": "Doctor",
      "text": "You’re on IV Dilaudid now. Pain should be manageable. We’ll switch you to oral meds like oxycodone once you can eat."
    },
    {
      "turn_number": 30,
      "time": "2125-02-24 13:33:00",
      "speaker": "Patient",
      "text": "Can I have water yet?"
    },
    {
      "turn_number": 31,
      "time": "2125-02-24 13:34:00",
      "speaker": "Doctor",
      "text": "Yes, start small sips. We’ll advance your diet as tolerated. We’re also giving IV fluids until you’re eating well."
    },
    {
      "turn_number": 32,
      "time": "2125-02-24 13:35:00",
      "speaker": "Patient",
      "text": "And the catheter—how do I care for it?"
    },
    {
      "turn_number": 33,
      "time": "2125-02-24 13:36:00",
      "speaker": "Doctor",
      "text": "The dressing stays on for now. Keep it dry. You can shower later, but no baths or swimming until your surgeon clears you."
    },
    {
      "turn_number": 34,
      "time": "2125-02-24 13:37:00",
      "speaker": "Patient",
      "text": "What if it leaks or gets red?"
    },
    {
      "turn_number": 35,
      "time": "2125-02-24 13:38:00",
      "speaker": "Doctor",
      "text": "Call your surgeon if there’s redness, swelling, pain, or drainage. Those could be signs of infection."
    },
    {
      "turn_number": 36,
      "time": "2125-02-25 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How’s the pain today?"
    },
    {
      "turn_number": 37,
      "time": "2125-02-25 09:01:00",
      "speaker": "Patient",
      "text": "Better. I took the oxycodone once yesterday."
    },
    {
      "turn_number": 38,
      "time": "2125-02-25 09:02:00",
      "speaker": "Doctor",
      "text": "Great. You’re tolerating a regular diet, and your vitals are stable. You walked a little yesterday—that’s excellent."
    },
    {
      "turn_number": 39,
      "time": "2125-02-25 09:03:00",
      "speaker": "Patient",
      "text": "I used my walker. My left leg feels weak after the amputation."
    },
    {
      "turn_number": 40,
      "time": "2125-02-25 09:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep encouraging mobility. It helps prevent clots. You’re also getting subcutaneous heparin for that."
    },
    {
      "turn_number": 41,
      "time": "2125-02-25 09:05:00",
      "speaker": "Patient",
      "text": "I forgot about that. Is it safe with the surgery?"
    },
    {
      "turn_number": 42,
      "time": "2125-02-25 09:06:00",
      "speaker": "Doctor",
      "text": "Yes, low-dose heparin reduces clot risk without high bleeding risk. We’re balancing both."
    },
    {
      "turn_number": 43,
      "time": "2125-02-25 09:07:00",
      "speaker": "Patient",
      "text": "And my heart meds? I take amiodarone and others."
    },
    {
      "turn_number": 44,
      "time": "2125-02-25 09:08:00",
      "speaker": "Doctor",
      "text": "You’re back on all your home meds: amiodarone, tacrolimus, sirolimus, aspirin, clopidogrel, and the rest."
    },
    {
      "turn_number": 45,
      "time": "2125-02-25 09:09:00",
      "speaker": "Patient",
      "text": "What about warfarin?"
    },
    {
      "turn_number": 46,
      "time": "2125-02-25 09:10:00",
      "speaker": "Doctor",
      "text": "We’re restarting it at a lower dose—3 mg total daily, now as three 1 mg tablets. It’s safer with the new catheter."
    },
    {
      "turn_number": 47,
      "time": "2125-02-25 09:11:00",
      "speaker": "Patient",
      "text": "Okay. And midodrine—still 5 mg twice a day?"
    },
    {
      "turn_number": 48,
      "time": "2125-02-25 09:12:00",
      "speaker": "Doctor",
      "text": "Yes, now as one 5 mg tablet twice daily. It’s helping your blood pressure stay stable."
    },
    {
      "turn_number": 49,
      "time": "2125-02-26 10:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re discharging you today to extended care for recovery."
    },
    {
      "turn_number": 50,
      "time": "2125-02-26 10:01:00",
      "speaker": "Patient",
      "text": "Already? What do I need to watch for?"
    },
    {
      "turn_number": 51,
      "time": "2125-02-26 10:02:00",
      "speaker": "Doctor",
      "text": "Weigh yourself every morning. Call if you gain more than 3 pounds. That could mean fluid buildup."
    },
    {
      "turn_number": 52,
      "time": "2125-02-26 10:03:00",
      "speaker": "Patient",
      "text": "And pain?"
    },
    {
      "turn_number": 53,
      "time": "2125-02-26 10:04:00",
      "speaker": "Doctor",
      "text": "Use oxycodone as needed, but don’t drive or operate machinery. You can also take Tylenol, just not more than 4000 mg a day."
    },
    {
      "turn_number": 54,
      "time": "2125-02-26 10:05:00",
      "speaker": "Patient",
      "text": "What about activity?"
    },
    {
      "turn_number": 55,
      "time": "2125-02-26 10:06:00",
      "speaker": "Doctor",
      "text": "Walk several times a day, but no heavy lifting—nothing over 10 pounds—until your surgeon says it’s okay."
    },
    {
      "turn_number": 56,
      "time": "2125-02-26 10:07:00",
      "speaker": "Patient",
      "text": "And my eye drops? I have glaucoma."
    },
    {
      "turn_number": 57,
      "time": "2125-02-26 10:08:00",
      "speaker": "Doctor",
      "text": "Yes, continue latanoprost at bedtime and the other drops as prescribed. Your vision is important."
    },
    {
      "turn_number": 58,
      "time": "2125-02-26 10:09:00",
      "speaker": "Patient",
      "text": "And my pancreas transplant? I don’t take insulin anymore."
    },
    {
      "turn_number": 59,
      "time": "2125-02-26 10:10:00",
      "speaker": "Doctor",
      "text": "Correct. Your pancreas transplant is functioning. Keep taking tacrolimus and sirolimus to prevent rejection."
    },
    {
      "turn_number": 60,
      "time": "2125-02-26 10:11:00",
      "speaker": "Patient",
      "text": "Thank you. I feel ready to go."
    },
    {
      "turn_number": 61,
      "time": "2125-02-26 10:12:00",
      "speaker": "Doctor",
      "text": "You’ve done really well. The catheter is in place, and you’re healing. Just follow up with your surgeon and primary doctor."
    },
    {
      "turn_number": 62,
      "time": "2125-02-26 10:13:00",
      "speaker": "Patient",
      "text": "I will. Thanks for explaining everything."
    },
    {
      "turn_number": 63,
      "time": "2125-02-26 10:14:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and call if anything changes."
    }
  ],
  "summary": {
    "admission_start": "2125-02-23 15:14:00",
    "admission_end": "2125-02-26 16:20:00",
    "summary_paragraph": "A woman with end-stage renal disease, a history of kidney and pancreas transplants, and multiple comorbidities was admitted for peritoneal dialysis catheter placement. She had been on hemodialysis and was holding warfarin in preparation for surgery. The procedure was performed successfully with lysis of peritoneal adhesions and creation of a cutaneoperitoneal fistula. Postoperatively, she had adequate pain control with IV and then oral analgesics, tolerated a regular diet, and ambulated with assistance. Her medications were adjusted, including increasing midodrine to 5 mg twice daily for blood pressure support and restarting warfarin at a reduced dose. She was discharged on postoperative day two to extended care with instructions on incision care, weight monitoring, activity restrictions, and medication management.",
    "problems": [
      "End stage renal disease",
      "Peritoneal adhesions (postoperative) (postinfection)",
      "Chronic diastolic heart failure",
      "Atrial fibrillation",
      "Anemia in chronic kidney disease",
      "Pancreas replaced by transplant",
      "Renal dialysis status",
      "Hypertensive chronic kidney disease, unspecified, with chronic kidney disease stage V or end stage renal disease",
      "Acute kidney failure, unspecified",
      "Below knee amputation status",
      "Diabetes with neurological manifestations, type I [juvenile type], not stated as uncontrolled",
      "Diabetes with ophthalmic manifestations, type I [juvenile type], not stated as uncontrolled",
      "Osteoporosis, unspecified",
      "Unspecified acquired hypothyroidism"
    ]
  }
}
